insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0001',1,'evidence','n','bằng chứng','Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.','Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.','proof','Archaeologists uncovered evidence that the coastal','History','foundation','{"context":{"id":"LIC_RV0001","vocabulary_id":"RV0001","headword":"evidence","pos":"n","meaning_vi":"bằng chứng","example_en":"Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.","example_vi":"Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.","topic":"History","related_expression_en":"proof","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0001","vocabulary_id":"RV0001","level":"foundation","direction":"en_vi","front":"evidence (n)","back":"bằng chứng","example_en":"Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.","example_vi":"Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.","grading":"self_rating"},{"id":"FC_VI_RV0001","vocabulary_id":"RV0001","level":"intermediate","direction":"vi_en","front":"bằng chứng","back":"evidence","disambiguation_en":"Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.","grading":"self_rating"}],"recall":{"id":"AR_RV0001","vocabulary_id":"RV0001","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Archaeologists uncovered ______ that the coastal settlement had been occupied for more than two thousand years.","context_translation_vi":"Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.","answer":"evidence","acceptable_answers":["evidence"],"explanation_vi":"Từ cần nhớ là ''evidence'' (n): bằng chứng.","grading":"self_report_or_exact_match_only_for_lemma","difficulty":"intermediate"},"translations":[{"id":"TR_ENVI_RV0001","vocabulary_id":"RV0001","stage":2,"tier":"intermediate","direction":"en_vi","prompt":"Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.","reference_answer":"Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.","target_vocabulary":"evidence","rubric_vi":"Đảm bảo đúng ý chính, quan hệ nguyên nhân–kết quả và nghĩa của từ trọng tâm; có thể có nhiều cách dịch tự nhiên.","auto_grade":false,"assessment":"self_compare_or_teacher"},{"id":"TR_VIEN_RV0001","vocabulary_id":"RV0001","stage":2,"tier":"advanced","direction":"vi_en","prompt":"Các nhà khảo cổ đã phát hiện bằng chứng cho thấy khu định cư ven biển này từng có người sinh sống hơn hai nghìn năm.","reference_answer":"Archaeologists uncovered evidence that the coastal settlement had been occupied for more than two thousand years.","target_vocabulary":"evidence","rubric_vi":"Câu trả lời có thể khác đáp án mẫu nếu chính xác về ý, ngữ pháp, thời và cấu trúc; không chấm bằng so khớp chuỗi.","auto_grade":false,"assessment":"self_compare_or_teacher"}]}'::jsonb,'642334c005685e34a06273568f8d51c7e1466e37d927abf982f1a935866768f6') on conflict (id) do nothing;
