insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0047',47,'noxious','adj','độc hại','Industrial facilities must control noxious emissions to protect workers and neighbouring residential areas.','Các cơ sở công nghiệp phải kiểm soát khí thải độc hại để bảo vệ người lao động và những khu dân cư lân cận.','harmful','must control noxious emissions to protect','Environment','advanced','{"context":{"id":"LIC_RV0047","vocabulary_id":"RV0047","headword":"noxious","pos":"adj","meaning_vi":"độc hại","example_en":"Industrial facilities must control noxious emissions to protect workers and neighbouring residential areas.","example_vi":"Các cơ sở công nghiệp phải kiểm soát khí thải độc hại để bảo vệ người lao động và những khu dân cư lân cận.","topic":"Environment","related_expression_en":"harmful","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0047","vocabulary_id":"RV0047","level":"foundation","direction":"en_vi","front":"noxious (adj)","back":"độc hại","example_en":"Industrial facilities must control noxious emissions to protect workers and neighbouring residential areas.","example_vi":"Các cơ sở công nghiệp phải kiểm soát khí thải độc hại để bảo vệ người lao động và những khu dân cư lân cận.","grading":"self_rating"},{"id":"FC_VI_RV0047","vocabulary_id":"RV0047","level":"intermediate","direction":"vi_en","front":"độc hại","back":"noxious","disambiguation_en":"Industrial facilities must control noxious emissions to protect workers and neighbouring residential areas.","grading":"self_rating"}],"recall":{"id":"AR_RV0047","vocabulary_id":"RV0047","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Industrial facilities must control ______ emissions to protect workers and ne