insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0048',48,'subsistence','n','mức sinh tồn tối thiểu','Subsistence farming remains important in remote regions where access to commercial markets is limited.','Nông nghiệp tự cung tự cấp vẫn quan trọng tại những vùng xa xôi có khả năng tiếp cận thị trường thương mại hạn chế.','basic survival','Subsistence farming remains important','Geography','advanced','{"context":{"id":"LIC_RV0048","vocabulary_id":"RV0048","headword":"subsistence","pos":"n","meaning_vi":"mức sinh tồn tối thiểu","example_en":"Subsistence farming remains important in remote regions where access to commercial markets is limited.","example_vi":"Nông nghiệp tự cung tự cấp vẫn quan trọng tại những vùng xa xôi có khả năng tiếp cận thị trường thương mại hạn chế.","topic":"Geography","related_expression_en":"basic survival","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0048","vocabulary_id":"RV0048","level":"foundation","direction":"en_vi","front":"subsistence (n)","back":"mức sinh tồn tối thiểu","example_en":"Subsistence farming remains important in remote regions where access to commercial markets is limited.","example_vi":"Nông nghiệp tự cung tự cấp vẫn quan trọng tại những vùng xa xôi có khả năng tiếp cận thị trường thương mại hạn chế.","grading":"self_rating"},{"id":"FC_VI_RV0048","vocabulary_id":"RV0048","level":"intermediate","direction":"vi_en","front":"mức sinh tồn tối thiểu","back":"subsistence","disambiguation_en":"Subsistence farming remains important in remote regions where access to commercial markets is limited.","grading":"self_rating"}],"recall":{"id":"AR_RV0048","vocabulary_id":"RV0048","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en