insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0050',50,'presumably','adv','có lẽ; theo suy đoán','The settlement was presumably abandoned after repeated floods damaged its agricultural land.','Khu định cư có lẽ đã bị bỏ hoang sau khi những trận lũ liên tiếp làm hư hại đất nông nghiệp.','apparently','settlement was presumably abandoned after repeated','History','intermediate','{"context":{"id":"LIC_RV0050","vocabulary_id":"RV0050","headword":"presumably","pos":"adv","meaning_vi":"có lẽ; theo suy đoán","example_en":"The settlement was presumably abandoned after repeated floods damaged its agricultural land.","example_vi":"Khu định cư có lẽ đã bị bỏ hoang sau khi những trận lũ liên tiếp làm hư hại đất nông nghiệp.","topic":"History","related_expression_en":"apparently","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0050","vocabulary_id":"RV0050","level":"foundation","direction":"en_vi","front":"presumably (adv)","back":"có lẽ; theo suy đoán","example_en":"The settlement was presumably abandoned after repeated floods damaged its agricultural land.","example_vi":"Khu định cư có lẽ đã bị bỏ hoang sau khi những trận lũ liên tiếp làm hư hại đất nông nghiệp.","grading":"self_rating"},{"id":"FC_VI_RV0050","vocabulary_id":"RV0050","level":"intermediate","direction":"vi_en","front":"có lẽ; theo suy đoán","back":"presumably","disambiguation_en":"The settlement was presumably abandoned after repeated floods damaged its agricultural land.","grading":"self_rating"}],"recall":{"id":"AR_RV0050","vocabulary_id":"RV0050","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"The settlement was ______ abandoned after repeated floods damaged its agricultural land.","context_translat