insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0074',74,'shoreline','n','đường bờ','Satellite images revealed that the shoreline had retreated significantly after several decades of coastal erosion.','Hình ảnh vệ tinh cho thấy đường bờ biển đã lùi đáng kể sau nhiều thập kỷ xói lở ven biển.','coastline','that the shoreline had retreated significantly','Environment','intermediate','{"context":{"id":"LIC_RV0074","vocabulary_id":"RV0074","headword":"shoreline","pos":"n","meaning_vi":"đường bờ","example_en":"Satellite images revealed that the shoreline had retreated significantly after several decades of coastal erosion.","example_vi":"Hình ảnh vệ tinh cho thấy đường bờ biển đã lùi đáng kể sau nhiều thập kỷ xói lở ven biển.","topic":"Environment","related_expression_en":"coastline","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0074","vocabulary_id":"RV0074","level":"foundation","direction":"en_vi","front":"shoreline (n)","back":"đường bờ","example_en":"Satellite images revealed that the shoreline had retreated significantly after several decades of coastal erosion.","example_vi":"Hình ảnh vệ tinh cho thấy đường bờ biển đã lùi đáng kể sau nhiều thập kỷ xói lở ven biển.","grading":"self_rating"},{"id":"FC_VI_RV0074","vocabulary_id":"RV0074","level":"intermediate","direction":"vi_en","front":"đường bờ","back":"shoreline","disambiguation_en":"Satellite images revealed that the shoreline had retreated significantly after several decades of coastal erosion.","grading":"self_rating"}],"recall":{"id":"AR_RV0074","vocabulary_id":"RV0074","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Satellite images revealed that the ______ had retreated significantly after several 