insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0101',101,'magnitude','n','độ lớn; quy mô','Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.','Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.','scale','underestimated the magnitude of the earthquake','Science','intermediate','{"context":{"id":"LIC_RV0101","vocabulary_id":"RV0101","headword":"magnitude","pos":"n","meaning_vi":"độ lớn; quy mô","example_en":"Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.","example_vi":"Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.","topic":"Science","related_expression_en":"scale","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0101","vocabulary_id":"RV0101","level":"foundation","direction":"en_vi","front":"magnitude (n)","back":"độ lớn; quy mô","example_en":"Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.","example_vi":"Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.","grading":"self_rating"},{"id":"FC_VI_RV0101","vocabulary_id":"RV0101","level":"intermediate","direction":"vi_en","front":"độ lớn; quy mô","back":"magnitude","disambiguation_en":"Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.","grading":"self_rating"}],"recall":{"id":"AR_RV0101","vocabulary_id":"RV0101","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Scientists underestimated the ______ of the earthquake because early measurements were incomplete.","context_translation_vi":"Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.","answer":"magnitude","acceptable_answers":["magnitude"],"explanation_vi":"Từ cần nhớ là ''magnitude'' (n): độ lớn; quy mô.","grading":"self_report_or_exact_match_only_for_lemma","difficulty":"intermediate"},"translations":[{"id":"TR_ENVI_RV0101","vocabulary_id":"RV0101","stage":2,"tier":"intermediate","direction":"en_vi","prompt":"Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.","reference_answer":"Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.","target_vocabulary":"magnitude","rubric_vi":"Đảm bảo đúng ý chính, quan hệ nguyên nhân–kết quả và nghĩa của từ trọng tâm; có thể có nhiều cách dịch tự nhiên.","auto_grade":false,"assessment":"self_compare_or_teacher"},{"id":"TR_VIEN_RV0101","vocabulary_id":"RV0101","stage":2,"tier":"advanced","direction":"vi_en","prompt":"Các nhà khoa học đã đánh giá thấp độ lớn của trận động đất vì những phép đo ban đầu chưa đầy đủ.","reference_answer":"Scientists underestimated the magnitude of the earthquake because early measurements were incomplete.","target_vocabulary":"magnitude","rubric_vi":"Câu trả lời có thể khác đáp án mẫu nếu chính xác về ý, ngữ pháp, thời và cấu trúc; không chấm bằng so khớp chuỗi.","auto_grade":false,"assessment":"self_compare_or_teacher"}]}'::jsonb,'642334c005685e34a06273568f8d51c7e1466e37d927abf982f1a935866768f6') on conflict (id) do nothing;
