insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0120',120,'persistent','adj','dai dẳng','Persistent noise pollution can affect sleep quality even when individuals become accustomed to its presence.','Ô nhiễm tiếng ồn kéo dài có thể ảnh hưởng đến chất lượng giấc ngủ ngay cả khi con người đã quen với nó.','continuing','Persistent noise pollution can','Environment','foundation','{"context":{"id":"LIC_RV0120","vocabulary_id":"RV0120","headword":"persistent","pos":"adj","meaning_vi":"dai dẳng","example_en":"Persistent noise pollution can affect sleep quality even when individuals become accustomed to its presence.","example_vi":"Ô nhiễm tiếng ồn kéo dài có thể ảnh hưởng đến chất lượng giấc ngủ ngay cả khi con người đã quen với nó.","topic":"Environment","related_expression_en":"continuing","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0120","vocabulary_id":"RV0120","level":"foundation","direction":"en_vi","front":"persistent (adj)","back":"dai dẳng","example_en":"Persistent noise pollution can affect sleep quality even when individuals become accustomed to its presence.","example_vi":"Ô nhiễm tiếng ồn kéo dài có thể ảnh hưởng đến chất lượng giấc ngủ ngay cả khi con người đã quen với nó.","grading":"self_rating"},{"id":"FC_VI_RV0120","vocabulary_id":"RV0120","level":"intermediate","direction":"vi_en","front":"dai dẳng","back":"persistent","disambiguation_en":"Persistent noise pollution can affect sleep quality even when individuals become accustomed to its presence.","grading":"self_rating"}],"recall":{"id":"AR_RV0120","vocabulary_id":"RV0120","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"______ noise pollution can affect sleep quality even when individuals b