insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0169',169,'incremental','adj','tăng dần từng bước','Incremental improvements in building insulation can produce significant energy savings over several decades.','Những cải tiến từng bước về cách nhiệt tòa nhà có thể mang lại mức tiết kiệm năng lượng đáng kể qua nhiều thập kỷ.','step-by-step','Incremental improvements in building','General academic','intermediate','{"context":{"id":"LIC_RV0169","vocabulary_id":"RV0169","headword":"incremental","pos":"adj","meaning_vi":"tăng dần từng bước","example_en":"Incremental improvements in building insulation can produce significant energy savings over several decades.","example_vi":"Những cải tiến từng bước về cách nhiệt tòa nhà có thể mang lại mức tiết kiệm năng lượng đáng kể qua nhiều thập kỷ.","topic":"General academic","related_expression_en":"step-by-step","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0169","vocabulary_id":"RV0169","level":"foundation","direction":"en_vi","front":"incremental (adj)","back":"tăng dần từng bước","example_en":"Incremental improvements in building insulation can produce significant energy savings over several decades.","example_vi":"Những cải tiến từng bước về cách nhiệt tòa nhà có thể mang lại mức tiết kiệm năng lượng đáng kể qua nhiều thập kỷ.","grading":"self_rating"},{"id":"FC_VI_RV0169","vocabulary_id":"RV0169","level":"intermediate","direction":"vi_en","front":"tăng dần từng bước","back":"incremental","disambiguation_en":"Incremental improvements in building insulation can produce significant energy savings over several decades.","grading":"self_rating"}],"recall":{"id":"AR_RV0169","vocabulary_id":"RV0169","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mớ