insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0177',177,'functionality','n','chức năng; khả năng hoạt động','The functionality of the device depends on its ability to operate reliably under extreme environmental conditions.','Chức năng hoạt động của thiết bị phụ thuộc vào khả năng vận hành đáng tin cậy trong điều kiện môi trường khắc nghiệt.','capability','The functionality of the device','General academic','intermediate','{"context":{"id":"LIC_RV0177","vocabulary_id":"RV0177","headword":"functionality","pos":"n","meaning_vi":"chức năng; khả năng hoạt động","example_en":"The functionality of the device depends on its ability to operate reliably under extreme environmental conditions.","example_vi":"Chức năng hoạt động của thiết bị phụ thuộc vào khả năng vận hành đáng tin cậy trong điều kiện môi trường khắc nghiệt.","topic":"General academic","related_expression_en":"capability","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0177","vocabulary_id":"RV0177","level":"foundation","direction":"en_vi","front":"functionality (n)","back":"chức năng; khả năng hoạt động","example_en":"The functionality of the device depends on its ability to operate reliably under extreme environmental conditions.","example_vi":"Chức năng hoạt động của thiết bị phụ thuộc vào khả năng vận hành đáng tin cậy trong điều kiện môi trường khắc nghiệt.","grading":"self_rating"},{"id":"FC_VI_RV0177","vocabulary_id":"RV0177","level":"intermediate","direction":"vi_en","front":"chức năng; khả năng hoạt động","back":"functionality","disambiguation_en":"The functionality of the device depends on its ability to operate reliably under extreme environmental conditions.","grading":"self_rating"}],"recall":{"id":"AR_RV0177","vocabula