insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0222',222,'minuscule','adj','cực kỳ nhỏ','Even a minuscule increase in average ocean temperature can affect highly sensitive marine ecosystems.','Ngay cả sự tăng rất nhỏ của nhiệt độ đại dương trung bình cũng có thể ảnh hưởng đến các hệ sinh thái biển cực kỳ nhạy cảm.','tiny','Even a minuscule increase in average','Technology','advanced','{"context":{"id":"LIC_RV0222","vocabulary_id":"RV0222","headword":"minuscule","pos":"adj","meaning_vi":"cực kỳ nhỏ","example_en":"Even a minuscule increase in average ocean temperature can affect highly sensitive marine ecosystems.","example_vi":"Ngay cả sự tăng rất nhỏ của nhiệt độ đại dương trung bình cũng có thể ảnh hưởng đến các hệ sinh thái biển cực kỳ nhạy cảm.","topic":"Technology","related_expression_en":"tiny","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0222","vocabulary_id":"RV0222","level":"foundation","direction":"en_vi","front":"minuscule (adj)","back":"cực kỳ nhỏ","example_en":"Even a minuscule increase in average ocean temperature can affect highly sensitive marine ecosystems.","example_vi":"Ngay cả sự tăng rất nhỏ của nhiệt độ đại dương trung bình cũng có thể ảnh hưởng đến các hệ sinh thái biển cực kỳ nhạy cảm.","grading":"self_rating"},{"id":"FC_VI_RV0222","vocabulary_id":"RV0222","level":"intermediate","direction":"vi_en","front":"cực kỳ nhỏ","back":"minuscule","disambiguation_en":"Even a minuscule increase in average ocean temperature can affect highly sensitive marine ecosystems.","grading":"self_rating"}],"recall":{"id":"AR_RV0222","vocabulary_id":"RV0222","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Even a ______ increase in average ocean temperat