insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0234',234,'detrimental','adj','có hại','Prolonged exposure to excessive noise can be detrimental to concentration and learning performance.','Việc tiếp xúc lâu dài với tiếng ồn quá mức có thể gây hại cho khả năng tập trung và kết quả học tập.','harmful','can be detrimental to concentration and','Education','advanced','{"context":{"id":"LIC_RV0234","vocabulary_id":"RV0234","headword":"detrimental","pos":"adj","meaning_vi":"có hại","example_en":"Prolonged exposure to excessive noise can be detrimental to concentration and learning performance.","example_vi":"Việc tiếp xúc lâu dài với tiếng ồn quá mức có thể gây hại cho khả năng tập trung và kết quả học tập.","topic":"Education","related_expression_en":"harmful","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0234","vocabulary_id":"RV0234","level":"foundation","direction":"en_vi","front":"detrimental (adj)","back":"có hại","example_en":"Prolonged exposure to excessive noise can be detrimental to concentration and learning performance.","example_vi":"Việc tiếp xúc lâu dài với tiếng ồn quá mức có thể gây hại cho khả năng tập trung và kết quả học tập.","grading":"self_rating"},{"id":"FC_VI_RV0234","vocabulary_id":"RV0234","level":"intermediate","direction":"vi_en","front":"có hại","back":"detrimental","disambiguation_en":"Prolonged exposure to excessive noise can be detrimental to concentration and learning performance.","grading":"self_rating"}],"recall":{"id":"AR_RV0234","vocabulary_id":"RV0234","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Prolonged exposure to excessive noise can be ______ to concentration and learning performance.","context_translation_vi":"V