insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0258',258,'causal','adj','thuộc quan hệ nhân quả','A statistical association does not necessarily establish a causal relationship between two observed variables.','Mối liên hệ thống kê không nhất thiết xác lập quan hệ nhân quả giữa hai biến được quan sát.','cause-related','establish a causal relationship between two','Science','advanced','{"context":{"id":"LIC_RV0258","vocabulary_id":"RV0258","headword":"causal","pos":"adj","meaning_vi":"thuộc quan hệ nhân quả","example_en":"A statistical association does not necessarily establish a causal relationship between two observed variables.","example_vi":"Mối liên hệ thống kê không nhất thiết xác lập quan hệ nhân quả giữa hai biến được quan sát.","topic":"Science","related_expression_en":"cause-related","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0258","vocabulary_id":"RV0258","level":"foundation","direction":"en_vi","front":"causal (adj)","back":"thuộc quan hệ nhân quả","example_en":"A statistical association does not necessarily establish a causal relationship between two observed variables.","example_vi":"Mối liên hệ thống kê không nhất thiết xác lập quan hệ nhân quả giữa hai biến được quan sát.","grading":"self_rating"},{"id":"FC_VI_RV0258","vocabulary_id":"RV0258","level":"intermediate","direction":"vi_en","front":"thuộc quan hệ nhân quả","back":"causal","disambiguation_en":"A statistical association does not necessarily establish a causal relationship between two observed variables.","grading":"self_rating"}],"recall":{"id":"AR_RV0258","vocabulary_id":"RV0258","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"A statistical association does not necessarily est