insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0293',293,'replicate','v','lặp lại; tái tạo','Independent laboratories attempted to replicate the experiment before accepting its surprising conclusions.','Các phòng thí nghiệm độc lập cố gắng lặp lại thí nghiệm trước khi chấp nhận những kết luận gây bất ngờ của nó.','reproduce','attempted to replicate the experiment before','Science','intermediate','{"context":{"id":"LIC_RV0293","vocabulary_id":"RV0293","headword":"replicate","pos":"v","meaning_vi":"lặp lại; tái tạo","example_en":"Independent laboratories attempted to replicate the experiment before accepting its surprising conclusions.","example_vi":"Các phòng thí nghiệm độc lập cố gắng lặp lại thí nghiệm trước khi chấp nhận những kết luận gây bất ngờ của nó.","topic":"Science","related_expression_en":"reproduce","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0293","vocabulary_id":"RV0293","level":"foundation","direction":"en_vi","front":"replicate (v)","back":"lặp lại; tái tạo","example_en":"Independent laboratories attempted to replicate the experiment before accepting its surprising conclusions.","example_vi":"Các phòng thí nghiệm độc lập cố gắng lặp lại thí nghiệm trước khi chấp nhận những kết luận gây bất ngờ của nó.","grading":"self_rating"},{"id":"FC_VI_RV0293","vocabulary_id":"RV0293","level":"intermediate","direction":"vi_en","front":"lặp lại; tái tạo","back":"replicate","disambiguation_en":"Independent laboratories attempted to replicate the experiment before accepting its surprising conclusions.","grading":"self_rating"}],"recall":{"id":"AR_RV0293","vocabulary_id":"RV0293","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Independent laboratories a