insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0304',304,'transient','adj','tạm thời; ngắn hạn','The rise in river temperature was transient and disappeared once the industrial discharge stopped.','Sự gia tăng nhiệt độ sông chỉ diễn ra trong thời gian ngắn và biến mất khi hoạt động xả thải công nghiệp chấm dứt.','short-lived','temperature was transient and disappeared once','Environment','advanced','{"context":{"id":"LIC_RV0304","vocabulary_id":"RV0304","headword":"transient","pos":"adj","meaning_vi":"tạm thời; ngắn hạn","example_en":"The rise in river temperature was transient and disappeared once the industrial discharge stopped.","example_vi":"Sự gia tăng nhiệt độ sông chỉ diễn ra trong thời gian ngắn và biến mất khi hoạt động xả thải công nghiệp chấm dứt.","topic":"Environment","related_expression_en":"short-lived","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0304","vocabulary_id":"RV0304","level":"foundation","direction":"en_vi","front":"transient (adj)","back":"tạm thời; ngắn hạn","example_en":"The rise in river temperature was transient and disappeared once the industrial discharge stopped.","example_vi":"Sự gia tăng nhiệt độ sông chỉ diễn ra trong thời gian ngắn và biến mất khi hoạt động xả thải công nghiệp chấm dứt.","grading":"self_rating"},{"id":"FC_VI_RV0304","vocabulary_id":"RV0304","level":"intermediate","direction":"vi_en","front":"tạm thời; ngắn hạn","back":"transient","disambiguation_en":"The rise in river temperature was transient and disappeared once the industrial discharge stopped.","grading":"self_rating"}],"recall":{"id":"AR_RV0304","vocabulary_id":"RV0304","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"The rise in river temperat