insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0312',312,'disproportionate','adj','không cân xứng','Low-income households may experience a disproportionate share of the health impacts caused by urban pollution.','Các hộ thu nhập thấp có thể phải gánh chịu tỷ lệ tác động sức khỏe từ ô nhiễm đô thị cao hơn mức tương xứng.','unequal','experience a disproportionate share of the','Environment','advanced','{"context":{"id":"LIC_RV0312","vocabulary_id":"RV0312","headword":"disproportionate","pos":"adj","meaning_vi":"không cân xứng","example_en":"Low-income households may experience a disproportionate share of the health impacts caused by urban pollution.","example_vi":"Các hộ thu nhập thấp có thể phải gánh chịu tỷ lệ tác động sức khỏe từ ô nhiễm đô thị cao hơn mức tương xứng.","topic":"Environment","related_expression_en":"unequal","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0312","vocabulary_id":"RV0312","level":"foundation","direction":"en_vi","front":"disproportionate (adj)","back":"không cân xứng","example_en":"Low-income households may experience a disproportionate share of the health impacts caused by urban pollution.","example_vi":"Các hộ thu nhập thấp có thể phải gánh chịu tỷ lệ tác động sức khỏe từ ô nhiễm đô thị cao hơn mức tương xứng.","grading":"self_rating"},{"id":"FC_VI_RV0312","vocabulary_id":"RV0312","level":"intermediate","direction":"vi_en","front":"không cân xứng","back":"disproportionate","disambiguation_en":"Low-income households may experience a disproportionate share of the health impacts caused by urban pollution.","grading":"self_rating"}],"recall":{"id":"AR_RV0312","vocabulary_id":"RV0312","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_e