insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0331',331,'cohesive','adj','gắn kết; mạch lạc','A cohesive transport strategy requires coordination between urban planners, environmental experts and local communities.','Một chiến lược giao thông gắn kết đòi hỏi sự phối hợp giữa nhà quy hoạch đô thị, chuyên gia môi trường và cộng đồng địa phương.','unified','A cohesive transport strategy requires','Society','advanced','{"context":{"id":"LIC_RV0331","vocabulary_id":"RV0331","headword":"cohesive","pos":"adj","meaning_vi":"gắn kết; mạch lạc","example_en":"A cohesive transport strategy requires coordination between urban planners, environmental experts and local communities.","example_vi":"Một chiến lược giao thông gắn kết đòi hỏi sự phối hợp giữa nhà quy hoạch đô thị, chuyên gia môi trường và cộng đồng địa phương.","topic":"Society","related_expression_en":"unified","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0331","vocabulary_id":"RV0331","level":"foundation","direction":"en_vi","front":"cohesive (adj)","back":"gắn kết; mạch lạc","example_en":"A cohesive transport strategy requires coordination between urban planners, environmental experts and local communities.","example_vi":"Một chiến lược giao thông gắn kết đòi hỏi sự phối hợp giữa nhà quy hoạch đô thị, chuyên gia môi trường và cộng đồng địa phương.","grading":"self_rating"},{"id":"FC_VI_RV0331","vocabulary_id":"RV0331","level":"intermediate","direction":"vi_en","front":"gắn kết; mạch lạc","back":"cohesive","disambiguation_en":"A cohesive transport strategy requires coordination between urban planners, environmental experts and local communities.","grading":"self_rating"}],"recall":{"id":"AR_RV0331","vocabulary_id":"RV0331","instruction_