insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0366',366,'encompass','v','bao gồm','The conservation programme aims to encompass both endangered species protection and local economic development.','Chương trình bảo tồn hướng tới bao gồm cả việc bảo vệ loài nguy cấp và phát triển kinh tế địa phương.','include','aims to encompass both endangered species','Environment','intermediate','{"context":{"id":"LIC_RV0366","vocabulary_id":"RV0366","headword":"encompass","pos":"v","meaning_vi":"bao gồm","example_en":"The conservation programme aims to encompass both endangered species protection and local economic development.","example_vi":"Chương trình bảo tồn hướng tới bao gồm cả việc bảo vệ loài nguy cấp và phát triển kinh tế địa phương.","topic":"Environment","related_expression_en":"include","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0366","vocabulary_id":"RV0366","level":"foundation","direction":"en_vi","front":"encompass (v)","back":"bao gồm","example_en":"The conservation programme aims to encompass both endangered species protection and local economic development.","example_vi":"Chương trình bảo tồn hướng tới bao gồm cả việc bảo vệ loài nguy cấp và phát triển kinh tế địa phương.","grading":"self_rating"},{"id":"FC_VI_RV0366","vocabulary_id":"RV0366","level":"intermediate","direction":"vi_en","front":"bao gồm","back":"encompass","disambiguation_en":"The conservation programme aims to encompass both endangered species protection and local economic development.","grading":"self_rating"}],"recall":{"id":"AR_RV0366","vocabulary_id":"RV0366","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"The conservation programme aims to ______ both endangered species protec