insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0455',455,'global','adj','toàn cầu','Global efforts to reduce emissions require cooperation between governments, industries and local communities.','Những nỗ lực toàn cầu nhằm giảm khí thải đòi hỏi sự hợp tác giữa chính phủ, các ngành công nghiệp và cộng đồng địa phương.','worldwide','Global efforts to reduce','Environment','foundation','{"context":{"id":"LIC_RV0455","vocabulary_id":"RV0455","headword":"global","pos":"adj","meaning_vi":"toàn cầu","example_en":"Global efforts to reduce emissions require cooperation between governments, industries and local communities.","example_vi":"Những nỗ lực toàn cầu nhằm giảm khí thải đòi hỏi sự hợp tác giữa chính phủ, các ngành công nghiệp và cộng đồng địa phương.","topic":"Environment","related_expression_en":"worldwide","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0455","vocabulary_id":"RV0455","level":"foundation","direction":"en_vi","front":"global (adj)","back":"toàn cầu","example_en":"Global efforts to reduce emissions require cooperation between governments, industries and local communities.","example_vi":"Những nỗ lực toàn cầu nhằm giảm khí thải đòi hỏi sự hợp tác giữa chính phủ, các ngành công nghiệp và cộng đồng địa phương.","grading":"self_rating"},{"id":"FC_VI_RV0455","vocabulary_id":"RV0455","level":"intermediate","direction":"vi_en","front":"toàn cầu","back":"global","disambiguation_en":"Global efforts to reduce emissions require cooperation between governments, industries and local communities.","grading":"self_rating"}],"recall":{"id":"AR_RV0455","vocabulary_id":"RV0455","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"______ efforts to reduce emissions