insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0456',456,'identify','v','xác định; nhận diện','Scientists used genetic analysis to identify previously unrecognised differences between two closely related species.','Các nhà khoa học sử dụng phân tích di truyền để xác định những khác biệt trước đây chưa được nhận biết giữa hai loài có quan hệ gần.','recognise','analysis to identify previously unrecognised differences','Environment','foundation','{"context":{"id":"LIC_RV0456","vocabulary_id":"RV0456","headword":"identify","pos":"v","meaning_vi":"xác định; nhận diện","example_en":"Scientists used genetic analysis to identify previously unrecognised differences between two closely related species.","example_vi":"Các nhà khoa học sử dụng phân tích di truyền để xác định những khác biệt trước đây chưa được nhận biết giữa hai loài có quan hệ gần.","topic":"Environment","related_expression_en":"recognise","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0456","vocabulary_id":"RV0456","level":"foundation","direction":"en_vi","front":"identify (v)","back":"xác định; nhận diện","example_en":"Scientists used genetic analysis to identify previously unrecognised differences between two closely related species.","example_vi":"Các nhà khoa học sử dụng phân tích di truyền để xác định những khác biệt trước đây chưa được nhận biết giữa hai loài có quan hệ gần.","grading":"self_rating"},{"id":"FC_VI_RV0456","vocabulary_id":"RV0456","level":"intermediate","direction":"vi_en","front":"xác định; nhận diện","back":"identify","disambiguation_en":"Scientists used genetic analysis to identify previously unrecognised differences between two closely related species.","grading":"self_rating"}],"recall":{"id":"AR_RV0456","