insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0462',462,'conservation','n','sự bảo tồn','Marine conservation programmes increasingly involve local fishing communities in decisions about protected areas.','Các chương trình bảo tồn biển ngày càng có sự tham gia của cộng đồng ngư dân địa phương trong quyết định về khu vực bảo vệ.','preservation','Marine conservation programmes increasingly involve','Environment','foundation','{"context":{"id":"LIC_RV0462","vocabulary_id":"RV0462","headword":"conservation","pos":"n","meaning_vi":"sự bảo tồn","example_en":"Marine conservation programmes increasingly involve local fishing communities in decisions about protected areas.","example_vi":"Các chương trình bảo tồn biển ngày càng có sự tham gia của cộng đồng ngư dân địa phương trong quyết định về khu vực bảo vệ.","topic":"Environment","related_expression_en":"preservation","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0462","vocabulary_id":"RV0462","level":"foundation","direction":"en_vi","front":"conservation (n)","back":"sự bảo tồn","example_en":"Marine conservation programmes increasingly involve local fishing communities in decisions about protected areas.","example_vi":"Các chương trình bảo tồn biển ngày càng có sự tham gia của cộng đồng ngư dân địa phương trong quyết định về khu vực bảo vệ.","grading":"self_rating"},{"id":"FC_VI_RV0462","vocabulary_id":"RV0462","level":"intermediate","direction":"vi_en","front":"sự bảo tồn","back":"conservation","disambiguation_en":"Marine conservation programmes increasingly involve local fishing communities in decisions about protected areas.","grading":"self_rating"}],"recall":{"id":"AR_RV0462","vocabulary_id":"RV0462","instruction_vi":"Đọc câu, tự nhớ từ t