insert into public.reading_vocabulary_entries (id,source_order,headword,pos,meaning_vi,example_en,example_vi,related_expression_en,context_chunk,topic,difficulty,content,source_archive_sha256) values ('RV0564',564,'compensate','v','bù đắp','Additional irrigation may compensate for reduced rainfall, although it can increase pressure on groundwater reserves.','Tưới tiêu bổ sung có thể bù đắp lượng mưa giảm, mặc dù có thể làm tăng áp lực lên nguồn nước ngầm.','make up for','irrigation may compensate for reduced rainfall','Environment','foundation','{"context":{"id":"LIC_RV0564","vocabulary_id":"RV0564","headword":"compensate","pos":"v","meaning_vi":"bù đắp","example_en":"Additional irrigation may compensate for reduced rainfall, although it can increase pressure on groundwater reserves.","example_vi":"Tưới tiêu bổ sung có thể bù đắp lượng mưa giảm, mặc dù có thể làm tăng áp lực lên nguồn nước ngầm.","topic":"Environment","related_expression_en":"make up for","learner_instruction_vi":"Đọc câu ví dụ, đoán nghĩa từ trong ngữ cảnh, sau đó xem nghĩa và bản dịch.","source_reference":"vocabulary_607.json"},"flashcards":[{"id":"FC_EN_RV0564","vocabulary_id":"RV0564","level":"foundation","direction":"en_vi","front":"compensate (v)","back":"bù đắp","example_en":"Additional irrigation may compensate for reduced rainfall, although it can increase pressure on groundwater reserves.","example_vi":"Tưới tiêu bổ sung có thể bù đắp lượng mưa giảm, mặc dù có thể làm tăng áp lực lên nguồn nước ngầm.","grading":"self_rating"},{"id":"FC_VI_RV0564","vocabulary_id":"RV0564","level":"intermediate","direction":"vi_en","front":"bù đắp","back":"compensate","disambiguation_en":"Additional irrigation may compensate for reduced rainfall, although it can increase pressure on groundwater reserves.","grading":"self_rating"}],"recall":{"id":"AR_RV0564","vocabulary_id":"RV0564","instruction_vi":"Đọc câu, tự nhớ từ tiếng Anh, rồi mới xem đáp án.","prompt_en":"Additional irrigation may ______ for reduced r